requests.preRequestScript:
// 1. Generate random data for profile updates
var timestamp = Date.now();
pw.env.set("randomValue", timestamp.toString());
pw.env.set("user_name", timestamp+" test");
pw.env.set("user_phone", timestamp.toString().substring(0, 10));
pw.env.set("user_company", timestamp.toString().substring(0, 8)+" S.A.");

// 2. Create unique user with timestamp
pw.env.unset("user_token");
let regEmail = timestamp + "@test.com";
let regPassword = timestamp + "_pw";
let regName = timestamp + " test";

let regResp = await fetch("https://practice.expandtesting.com/notes/api/users/register", {
    method: "POST",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify({
        name: regName,
        email: regEmail,
        password: regPassword
    })
});

let regData = await regResp.json();
console.log("Register:", regData.success);

if (regData.success && regData.data) {
    pw.env.set("user_id", regData.data.id);

    let loginResp = await fetch("https://practice.expandtesting.com/notes/api/users/login", {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify({
            email: regEmail,
            password: regPassword
        })
    });

    let loginData = await loginResp.json();
    console.log("Login:", loginData.success);
    if (loginData.success && loginData.data && loginData.data.token) {
        pw.env.set("user_token", loginData.data.token);
    } else {
        console.log("Login failed:", loginData.message);
    }
} else {
    console.log("Register failed:", regData.message);
}

