// ===== POST-REQUEST SCRIPT =====

// Delete user account
let baseUrl = pw.env.get("base_url");
let token = pw.env.get("user_token");

if (token) {
    try {
        await fetch(baseUrl + "/users/delete-account", {
            method: "DELETE",
            headers: {"X-Auth-Token": token}
        });
    } catch(e) {}
}

// Clean environment (apenas variáveis criadas no pre/test)
