requests.preRequestScript:
// 1. Generate random data
var random = Math.floor(Math.random() * 1000) + 1000;
pw.env.set("randomValue", random.toString());
pw.env.set("user_name", random + " test");
pw.env.set("user_email", "1" + random + "@test.com");
pw.env.set("user_password", random + "_pw");

// 2. Register user
let baseUrl = pw.env.get("base_url");
let regResp = await fetch(baseUrl + "/users/register", {
    method: "POST",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify({
        name: pw.env.get("user_name"),
        email: pw.env.get("user_email"),
        password: pw.env.get("user_password")
    })
});

let regData = await regResp.json();
if (regData.success && regData.data) {
    pw.env.set("user_id", regData.data.id);

    // 3. Login
    let loginResp = await fetch(baseUrl + "/users/login", {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify({
            email: pw.env.get("user_email"),
            password: pw.env.get("user_password")
        })
    });

    let loginData = await loginResp.json();
    if (loginData.success && loginData.data && loginData.data.token) {
        pw.env.set("user_token", loginData.data.token);
    }
}

